// One row per keyword for this week. Running the same list every Monday
// turns the sheet into a history you can chart or pivot.
const settings = $('Set your keywords').first().json;
const weekOf = $now.toFormat('yyyy-MM-dd');

return $input.all()
  .filter((item) => item.json.keyword)
  .map(({ json: k }) => ({
    json: {
      'Week of': weekOf,
      Keyword: k.keyword,
      Country: settings.location,
      'Search volume': k.search_volume ?? '',
      CPC: k.cpc ?? '',
      Competition: k.competition_level ?? '',
      'Keyword difficulty': k.keyword_difficulty ?? '',
      Intent: k.search_intent ?? '',
      'AI search volume': k.ai_search_volume ?? '',
      'AI Overview': (k.serp_features ?? []).includes('ai_overview') ? 'YES' : '',
      Status: k.data_status ?? '',
    },
  }));
